# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">UNIVERSAL DECLARATION OF HUMAN RIGHTS (UDHR - 1948)</text>\n  <!-- Left Box -->\n  <rect x="25" y="45" width="315" height="198" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">HISTORICAL MILESTONE</text>\n  <text x="40" y="92" font-size="12" fill="#1e3a8a">• Adopted by the UN General Assembly in Paris</text>\n  <text x="50" y="110" font-size="12" font-weight="bold" fill="#1d4ed8">on December 10, 1948 (30 Articles).</text>\n  <text x="40" y="132" font-size="12" fill="#1e3a8a">• Drafting Committee Chair: Eleanor Roosevelt.</text>\n  <text x="40" y="154" font-size="12" fill="#1e3a8a">• Core Principle (Article 1): "All human beings</text>\n  <text x="50" y="172" font-size="12" fill="#1e3a8a">are born free and equal in dignity and rights."</text>\n  <rect x="42" y="186" width="280" height="44" rx="6" fill="#dbeafe"/>\n  <text x="182" y="205" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Key Vocabulary:</text>\n  <text x="182" y="221" text-anchor="middle" font-size="11" fill="#1e3a8a">dignity (onur) • equality (eşitlik) • justice (adalet)</text>\n  <!-- Right Box -->\n  <rect x="360" y="45" width="315" height="198" rx="10" fill="#ecfdf5" stroke="#059669" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#065f46">FUNDAMENTAL RIGHTS &amp; FREEDOMS</text>\n  <text x="375" y="92" font-size="12" fill="#047857">• Right to life, liberty and personal security</text>\n  <text x="375" y="114" font-size="12" fill="#047857">• Freedom from slavery, torture and discrimination</text>\n  <text x="375" y="136" font-size="12" fill="#047857">• Right to a fair trial and equality before the law</text>\n  <text x="375" y="158" font-size="12" fill="#047857">• Freedom of thought, conscience and expression</text>\n  <text x="375" y="180" font-size="12" fill="#047857">• Right to education, work and healthcare</text>\n  <rect x="377" y="192" width="280" height="38" rx="6" fill="#d1fae5"/>\n  <text x="517" y="215" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#065f46">Human rights are universal and inalienable.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">SUPPORTING DISADVANTAGED PEOPLE &amp; EMPATHETIC LANGUAGE</text>\n  <!-- Left: Solutions -->\n  <rect x="25" y="45" width="315" height="198" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="182" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">SOCIAL INCLUSION &amp; SOLUTIONS</text>\n  <text x="40" y="94" font-size="12" fill="#78350f">• Accessibility: Building wheelchair ramps, tactile</text>\n  <text x="50" y="111" font-size="12" fill="#78350f">pavements, Braille texts and audio guides.</text>\n  <text x="40" y="135" font-size="12" fill="#78350f">• Equal Opportunity: Providing scholarships and</text>\n  <text x="50" y="152" font-size="12" fill="#78350f">micro-enterprise support for low-income families.</text>\n  <text x="40" y="176" font-size="12" fill="#78350f">• Volunteering: Supporting shelters, food banks,</text>\n  <text x="50" y="193" font-size="12" fill="#78350f">refugees and elderly care centres.</text>\n  <text x="40" y="218" font-size="11.5" font-weight="bold" fill="#b45309">Goal: Overcoming prejudice and discrimination.</text>\n  <!-- Right: Expressions -->\n  <rect x="360" y="45" width="315" height="198" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">MAKING SUGGESTIONS &amp; PROPOSALS</text>\n  <text x="375" y="94" font-size="12" fill="#581c87">• "We should / ought to ensure equal access..."</text>\n  <text x="375" y="118" font-size="12" fill="#581c87">• "It is essential / vital to protect vulnerable..."</text>\n  <text x="375" y="142" font-size="12" fill="#581c87">• "Why don\'t we organize a charity campaign?"</text>\n  <text x="375" y="166" font-size="12" fill="#581c87">• "How about volunteering at the community centre?"</text>\n  <rect x="377" y="182" width="280" height="48" rx="6" fill="#f3e8ff"/>\n  <text x="517" y="201" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#6b21a8">Respectful Terminology:</text>\n  <text x="517" y="218" text-anchor="middle" font-size="11" fill="#581c87">Use "people with disabilities" or "visually impaired"</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">HUMAN RIGHTS MOTTOS, WATCHWORDS &amp; THEME REVIEW</text>\n  <!-- 4 Motto Cards -->\n  <rect x="25" y="48" width="315" height="85" rx="8" fill="#dbeafe" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="182" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">"Human Rights Are Everyone\'s Rights!"</text>\n  <text x="182" y="93" text-anchor="middle" font-size="11.5" fill="#1e3a8a">İnsan hakları ayrıcalık değil, doğuştan kazanılan</text>\n  <text x="182" y="110" text-anchor="middle" font-size="11.5" fill="#1e3a8a">evrensel ve devredilemez haklardır.</text>\n\n  <rect x="360" y="48" width="315" height="85" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="1.8"/>\n  <text x="517" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">"No One Is Free Until Everyone Is Free!"</text>\n  <text x="517" y="93" text-anchor="middle" font-size="11.5" fill="#14532d">Toplumda adalet ve özgürlük bölünmez bir</text>\n  <text x="517" y="110" text-anchor="middle" font-size="11.5" fill="#14532d">bütündür; ayrımcılığa karşı dayanışma şarttır.</text>\n\n  <rect x="25" y="148" width="315" height="92" rx="8" fill="#fef2f2" stroke="#dc2626" stroke-width="1.8"/>\n  <text x="182" y="172" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#991b1b">"Stand Up for Equality, Speak Up for Justice!"</text>\n  <text x="182" y="193" text-anchor="middle" font-size="11.5" fill="#7f1d1d">Imperative (Emir kipi) ve paralel yapı kullanılarak</text>\n  <text x="182" y="210" text-anchor="middle" font-size="11.5" fill="#7f1d1d">etkili ve akılda kalıcı özdeyişler (mottos) oluşturulur.</text>\n\n  <rect x="360" y="148" width="315" height="92" rx="8" fill="#fff7ed" stroke="#ea580c" stroke-width="1.8"/>\n  <text x="517" y="172" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9a3412">"Respect Differences, Embrace Diversity!"</text>\n  <text x="517" y="193" text-anchor="middle" font-size="11.5" fill="#7c2d12">Farklılıklara saygı duymak ve çeşitliliği</text>\n  <text x="517" y="210" text-anchor="middle" font-size="11.5" fill="#7c2d12">kucaklamak toplumsal barışın anahtarıdır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
